+        </tr></thead>
+        <tbody>{event.matches.map((match, index) => {
+          const players = matchPlayers(event, index);
+          return <tr key={match.boardCode}>
+            <td>{tournamentRound(event.players.length, index).name}</td>
+            <td>{index + 1}</td>
+            {[0, 1].map((turn) => {
+              const result = match.results[turn];
+              return <TournamentCells key={turn} name={name(players[turn]) ?? ''}
+                moves={result?.moves} elapsedMs={result?.elapsedMs} />;
+            })}
+            <td>{name(matchWinner(event, index))}</td>
+          </tr>;
+        })}</tbody>
+      </table>
+    </div>
